 [Fact] public async Task Atualizacao_v4_adiciona_campos_da_v41(){db.Settings.Add(new PortalSetting{Key="legacy-import",Value="test"});await db.SaveChangesAsync();foreach(var item in new[]{("Progress","InternalNotes"),("Progress","LessonId"),("Payments","History"),("Lessons","CancellationReason")})await db.Database.ExecuteSqlRawAsync("ALTER TABLE "+item.Item1+" DROP COLUMN "+item.Item2);using var oldConnection=new SqliteConnection("Data Source=:memory:");oldConnection.Open();using var old=new SistemaPedagogico.Infrastructure.Data.SistemaPedagogicoDbContext(new DbContextOptionsBuilder<SistemaPedagogico.Infrastructure.Data.SistemaPedagogicoDbContext>().UseSqlite(oldConnection).Options);await PortalBootstrap.ImportAsync(db,old);db.ChangeTracker.Clear();Assert.Equal(2,await db.Students.CountAsync());await db.Progress.AddAsync(new Progress{StudentId=1,InternalNotes="Privado"});await db.Lessons.AddAsync(new Lesson{StudentId=1,CancellationReason="Imprevisto"});await db.SaveChangesAsync();Assert.Equal("Privado",(await db.Progress.SingleAsync()).InternalNotes);Assert.Equal("Imprevisto",(await db.Lessons.SingleAsync()).CancellationReason);}

